<script setup lang="ts">
import { computed,ref } from 'vue';import type { ViewModel } from '../app/useWorkspace';
const props=defineProps<{w:ViewModel;kind:'relations'|'chronicle'|'map'}>();
const chosen=ref('guide'),place=ref('');const positions=ref<Record<string,{x:number;y:number}>>({player:{x:260,y:150},guide:{x:120,y:70},engineer:{x:400,y:235}});
const actor=computed(()=>props.w.state?.characters.find(a=>a.id===chosen.value));let dragging:string|undefined;let moved=false;
const places=[{id:'reception',name:'接待区',description:'虚构样例：公共接待设施的介绍。点击只查看资料，不产生移动。',x:35,y:55},{id:'archive',name:'公开资料室',description:'虚构样例：用于展示地图的公开说明。这里没有探索或地点事件。',x:245,y:55},{id:'platform',name:'观景平台',description:'虚构样例：一处站点设施。地点说明不包含私有世界观原文。',x:140,y:170}];
function down(id:string,e:PointerEvent){dragging=id;moved=false;(e.currentTarget as SVGElement).setPointerCapture(e.pointerId);}
function move(e:PointerEvent){if(!dragging)return;const svg=(e.currentTarget as SVGSVGElement),r=svg.getBoundingClientRect();positions.value[dragging]={x:Math.max(45,Math.min(475,(e.clientX-r.left)*520/r.width)),y:Math.max(35,Math.min(285,(e.clientY-r.top)*320/r.height))};moved=true;}
function up(){if(dragging&&dragging!=='player')chosen.value=dragging;dragging=undefined;}
function source(id:string){props.w.panel='story';setTimeout(()=>document.getElementById(`turn-${id}`)?.scrollIntoView({block:'center'}),100);}
</script>
<template>
  <section v-if="kind==='relations'&&w.state" class="surface"><p class="eyebrow">RELATIONS / 人物关系</p><h1>当前已知的人物关系</h1><p class="muted">可拖动节点。这里移动的是图中节点，游戏人物不会移动。</p><svg class="relation-graph" viewBox="0 0 520 320" role="img" aria-label="玩家与两名样例角色的关系图" @pointermove="move" @pointerup="up" @pointercancel="up"><line v-for="a in w.state.characters" :key="`line-${a.id}`" :x1="positions.player.x" :y1="positions.player.y" :x2="positions[a.id]?.x||260" :y2="positions[a.id]?.y||150" /><g v-for="a in [w.state.player,...w.state.characters]" :key="a.id" :transform="`translate(${positions[a.id]?.x||260},${positions[a.id]?.y||150})`" @pointerdown="down(a.id,$event)"><circle r="27" /><text y="45" text-anchor="middle">{{a.name}}</text><text v-if="a.id!=='player'" y="5" text-anchor="middle">{{a.affinity}}</text></g></svg><div class="actions"><button v-for="a in w.state.characters" :key="a.id" :class="{selected:chosen===a.id}" @click="chosen=a.id">{{a.name}}</button></div><div v-if="actor" class="detail"><h2>{{actor.name}}</h2><p>已知关系值 {{actor.affinity}} / 100 · {{actor.present?'当前在场':'不在场'}}</p><p class="muted">仅展示公开状态，没有私有心声或完整人设。</p></div></section>
  <section v-else-if="kind==='chronicle'" class="surface"><p class="eyebrow">CHRONICLE / 编年史</p><h1>每一幕留下的事件</h1><p class="muted">首版按回合展示；游戏内日期将在正式资料接入时补充。</p><ol class="chronicle"><li v-for="event in w.events" :key="event.turnId"><span class="tag">第 {{event.index}} 幕</span><p>{{event.title}}</p><button @click="source(event.turnId)">回看原文</button></li></ol><p v-if="!w.events.length" class="empty">完整剧情回合后，事件会出现在这里。</p></section>
  <section v-else-if="kind==='map'" class="surface"><p class="eyebrow">MAP / 点击地图</p><h1>地点资料</h1><p class="muted">这是示意图样例。只点击查看介绍，没有当前位置、路线、移动或事件。</p><svg class="static-map" viewBox="0 0 460 270" role="img" aria-label="可点击的站点资料示意图"><rect x="12" y="12" width="436" height="246" rx="4" class="map-outline" /><g v-for="p in places" :key="p.id" :transform="`translate(${p.x},${p.y})`" @click="place=p.id"><rect width="180" height="65" rx="4" /><text x="90" y="37" text-anchor="middle">{{p.name}}</text></g></svg><div class="actions"><button v-for="p in places" :key="p.id" :class="{selected:place===p.id}" @click="place=p.id">{{p.name}}</button></div><article v-if="place" class="detail"><h2>{{places.find(p=>p.id===place)?.name}}</h2><p>{{places.find(p=>p.id===place)?.description}}</p></article><p v-else class="empty">点击一个地点，查看公开介绍。</p></section>
</template>

